import 'package:flutter_base/ui.dart';

/// SVG 的绘制读取最近 ElView 已提交的文字色，主题和颜色动画不会重建图标。
class MyGlyph extends LeafRenderObjectWidget {
  /// 内置图标或加载圆弧。
  const MyGlyph({super.key, this.name = '', this.spinner = false});

  /// 与Web相同的图标名称。
  final String name;

  /// 是否绘制加载圆弧。
  final bool spinner;

  @override
  RenderObject createRenderObject(BuildContext context) =>
      _GlyphRender(name, spinner);

  @override
  void updateRenderObject(
    BuildContext context,
    covariant RenderBox renderObject,
  ) => (renderObject as _GlyphRender).configure(name, spinner);
}

class _GlyphRender extends RenderBox {
  _GlyphRender(this._name, this._spinner);
  String _name;
  bool _spinner;

  void configure(String name, bool spinner) {
    if (_name == name && _spinner == spinner) return;
    _name = name;
    _spinner = spinner;
    markNeedsPaint();
  }

  @override
  Size computeDryLayout(BoxConstraints constraints) =>
      constraints.constrain(const Size(24, 24));

  @override
  void performLayout() => size = computeDryLayout(constraints);

  @override
  void paint(PaintingContext context, Offset offset) {
    var ancestor = parent;
    var color = const Color(0xff17191e);
    while (ancestor != null) {
      if (ancestor is ElRenderView && ancestor.currentColorForBuild != null) {
        color = ancestor.currentColorForBuild!;
        break;
      }
      ancestor = ancestor.parent;
    }
    final canvas = context.canvas;
    canvas
      ..save()
      ..translate(offset.dx, offset.dy)
      ..scale(size.width / 24, size.height / 24);
    final paint = Paint()
      ..style = PaintingStyle.stroke
      ..color = color
      ..strokeWidth = _spinner ? 2.5 : 1.8
      ..strokeCap = StrokeCap.round
      ..strokeJoin = StrokeJoin.round;
    if (_spinner) {
      // 原版 circle r=9、dasharray=42 16，首段从圆的右侧开始。
      canvas.drawArc(
        const Rect.fromLTWH(3, 3, 18, 18),
        0,
        42 / 9,
        false,
        paint,
      );
    } else {
      final name = _iconMarkup.containsKey(_name) ? _name : 'sun';
      for (final path in _iconPaths.putIfAbsent(
        name,
        () => _compileIcon(_iconMarkup[name]!),
      )) {
        canvas.drawPath(path, paint);
      }
    }
    canvas.restore();
  }
}

final _iconPaths = <String, List<Path>>{};

List<Path> _compileIcon(String markup) {
  final result = <Path>[];
  for (final element in RegExp(
    r'<(path|circle|rect)\b([^>]*)/?>',
  ).allMatches(markup)) {
    final attrs = <String, String>{
      for (final attr in RegExp(r'([\w-]+)="([^"]*)"').allMatches(element[2]!))
        attr[1]!: attr[2]!,
    };
    double number(String name, [double fallback = 0]) =>
        double.tryParse(attrs[name] ?? '') ?? fallback;
    switch (element[1]) {
      case 'path':
        result.add(_svgPath(attrs['d']!));
      case 'circle':
        result.add(
          Path()..addOval(
            Rect.fromCircle(
              center: Offset(number('cx'), number('cy')),
              radius: number('r'),
            ),
          ),
        );
      case 'rect':
        result.add(
          Path()..addRRect(
            RRect.fromRectAndRadius(
              Rect.fromLTWH(
                number('x'),
                number('y'),
                number('width'),
                number('height'),
              ),
              Radius.circular(number('rx')),
            ),
          ),
        );
    }
  }
  return result;
}

/// 只解析原图标使用的 SVG 指令，曲线与椭圆弧直接交给 Canvas，避免字体轮廓采样误差。
Path _svgPath(String source) {
  final tokens = RegExp(r'[a-zA-Z]|[-+]?(?:\d*\.?\d+)(?:[eE][-+]?\d+)?')
      .allMatches(source)
      .map((match) => match[0]!)
      .toList();
  final path = Path();
  var index = 0, command = '';
  var current = Offset.zero, start = Offset.zero;
  Offset? cubic;
  String previous = '';
  double read() => double.parse(tokens[index++]);
  bool isCommand(String value) => RegExp(r'^[a-zA-Z]$').hasMatch(value);
  while (index < tokens.length) {
    if (isCommand(tokens[index])) command = tokens[index++];
    final relative = command == command.toLowerCase();
    final op = command.toUpperCase();
    Offset point() {
      final value = Offset(read(), read());
      return relative ? current + value : value;
    }

    switch (op) {
      case 'M':
        current = point();
        start = current;
        path.moveTo(current.dx, current.dy);
        command = relative ? 'l' : 'L';
      case 'L':
        current = point();
        path.lineTo(current.dx, current.dy);
      case 'H':
        current = Offset((relative ? current.dx : 0) + read(), current.dy);
        path.lineTo(current.dx, current.dy);
      case 'V':
        current = Offset(current.dx, (relative ? current.dy : 0) + read());
        path.lineTo(current.dx, current.dy);
      case 'C':
        final first = point(), second = point(), end = point();
        path.cubicTo(first.dx, first.dy, second.dx, second.dy, end.dx, end.dy);
        cubic = second;
        current = end;
      case 'S':
        final first = (previous == 'C' || previous == 'S') && cubic != null
            ? current * 2 - cubic
            : current;
        final second = point(), end = point();
        path.cubicTo(first.dx, first.dy, second.dx, second.dy, end.dx, end.dy);
        cubic = second;
        current = end;
      case 'A':
        final radius = Radius.elliptical(read(), read()), rotation = read();
        final large = read() != 0, clockwise = read() != 0;
        current = point();
        path.arcToPoint(
          current,
          radius: radius,
          rotation: rotation,
          largeArc: large,
          clockwise: clockwise,
        );
      case 'Z':
        path.close();
        current = start;
        command = '';
      default:
        throw FormatException('不支持的原图标路径指令：$command', source);
    }
    if (op != 'C' && op != 'S') cubic = null;
    previous = op;
  }
  return path;
}

