              await _save(tester, boundary, 'flutter-state-$key-pressed');
              await mouse.up();
              await mouse.removePointer();
              await tester.pumpAndSettle();
              expect(tester.takeException(), isNull);
            }
          }
          await tester.pumpWidget(SizedBox());
          await tester.pumpAndSettle();
        }
        await tester.runAsync(
